mapper.select:
select g.id as goodsId, g.`name` as name, g.pic_url as picUrl, g.is_on_sale as isOnSale, g.retail_price as retailPrice, case when g.cost > 0 then g.cost end as cost, case when g.cost > 0 then g.retail_price - g.cost end as marginAmount, case when g.cost > 0 and g.retail_price > 0 then round((g.retail_price - g.cost) / g.retail_price * 100, 2) end as marginPct, coalesce(p.stock_total, 0) as stockTotal, md.available as cjAvailable, g.add_time as arrivalDate, coalesce(s.sales_qty, 0) as salesQty from litemall_goods g left join () p on p.goods_id = g.id left join () s on s.goods_id = g.id left join litemall_product_metric_daily md on md.goods_id = g.id and md.`day` = #{day} where g.deleted = 0
and g.category_id in #{cid}
order by
g.retail_price marginPct stockTotal salesQty g.add_time
asc desc
, g.id desc limit #{limit} offset #{offset}

select count(*) as onSaleCount, coalesce(sum(case when g.cost > 0 then 1 else 0 end), 0) as costedCount, coalesce(sum(case when g.cost > 0 then 0 else 1 end), 0) as uncostedCount, round(max(case when g.cost > 0 and g.retail_price > 0 then g.cost / g.retail_price end), 4) as maxCostRatio, min(g.retail_price) as minRetailPrice from litemall_goods g where g.deleted = 0 and g.is_on_sale = 1
and (
g.id in #{gid}
or g.category_id in #{cid}
)
